def extract(prefix,slug,first=0,limit=3):
 existing=[A/f'{slug}-{j}.webp' for j in range(limit)]
 if all(p.exists() for p in existing):return ['/assets/'+p.name for p in existing]
 z=next(U.glob(prefix+'*1).zip')); result=[]
 with zipfile.ZipFile(z) as f:
  names=[n for n in f.namelist() if n.lower().endswith(('.jpg','.png','.jpeg'))]
  order=[first]+[i for i in range(len(names)) if i!=first]
  for j,i in enumerate(order[:limit]):
   p=A/f'{slug}-{j}.webp'; im=ImageOps.exif_transpose(Image.open(io.BytesIO(f.read(names[i])))).convert('RGB'); im.thumbnail((1400,1400));im.save(p,'WEBP',quality=84);result.append('/assets/'+p.name)
 return result
