 # Reserve intrinsic image space to prevent layout shifts and premature reveals.
 def dimensions(match):
  tag=match.group(0); src=re.search(r'src="(/assets/[^"?]+)"',tag)
  if src and 'width=' not in tag:
   asset=D/src.group(1).lstrip('/')
   if asset.exists():
    with Image.open(asset) as picture:w,h=picture.size
    return tag[:-1]+f' width="{w}" height="{h}">'
  return tag
 h=re.sub(r'<img\b[^>]*>',dimensions,h)
 # Product images: wrap for hover zoom, red frame and a "view details" button.
 h=re.sub(r'(<a class="(?:product-card|mosaic-item)[^"]*"[^>]*>)(<img\b[^>]*>)',r'\1<span class="card-media">\2<em class="view-detail">Xem chi tiết</em></span>',h)
